SELECT (SELECT COUNT(*) FROM VIDEOS WHERE FAVORITO = 1 AND STATUS <> 'FORA') VIDEOS, (SELECT COUNT(*) FROM PRATICAS WHERE FAVORITA = 1) PRATICAS, (SELECT COUNT(*) FROM ITENS_FAVORITOS WHERE TIPO = 'LIVRO') LIVROS, (SELECT COUNT(*) FROM ITENS_FAVORITOS WHERE TIPO = 'MUSICA') MUSICAS, (SELECT COUNT(*) FROM ITENS_FAVORITOS WHERE TIPO = 'AUDIOVISUAL') AUDIOVISUAIS, (SELECT COUNT(*) FROM ITENS_FAVORITOS WHERE TIPO = 'SAGRADO') SAGRADOS